// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  AppWindowIcon,
  ArrowDownToLineIcon,
  ArrowLeftIcon,
  ArrowRightIcon,
  ArrowUpToLineIcon,
  CheckIcon,
  ClipboardListIcon,
  CodeXmlIcon,
  CopyIcon,
  CopyPlusIcon,
  EraserIcon,
  GlobeIcon,
  HashIcon,
  LinkIcon,
  ListIcon,
  LockIcon,
  MinusIcon,
  PencilLineIcon,
  PinIcon,
  PlusIcon,
  PrinterIcon,
  QrCodeIcon,
  CameraIcon,
  RotateCwIcon,
  TypeIcon,
  VenetianMaskIcon,
  Volume2Icon,
  ZapIcon,
  ZoomInIcon,
  type LucideIcon,
} from 'lucide-react'
import type { ReactNode } from 'react'

import { BrowserChrome, DemoStage, DockHeader, type Build } from '@/app/demos/stage'

import {
  CAPTIONS,
  CLEAN,
  COPY_ITEMS,
  EDIT,
  HEADLINE,
  HOST,
  MARKDOWN,
  PATH,
  TITLE,
  URL_TEXT,
  ZOOMS,
} from './script'

const PANEL = 256
const COPY_ICONS: Record<string, LucideIcon> = {
  url: LinkIcon,
  title: TypeIcon,
  both: ClipboardListIcon,
  md: HashIcon,
  html: CodeXmlIcon,
  domain: GlobeIcon,
  clean: EraserIcon,
  all: ListIcon,
}

const build: Build = ({ tl, q, qa, step, final, move, click, type, wait, cursorOut }) => {
  const done = (key: string) => {
    tl.to(q(`icon-${key}`), { opacity: 0, duration: 0.1 }, '<')
    tl.to(q(`ok-${key}`), { opacity: 1, duration: 0.1 }, '<')
    tl.to(q(`tile-${key}`), { borderColor: 'rgba(52,211,153,0.5)', duration: 0.15 }, '<')
  }
  const clipboard = (title: string, text: string) => {
    tl.set(q('clip-title'), { text: title })
    tl.set(q('clip-text'), { text })
    tl.fromTo(
      q('clip'),
      { opacity: 0, y: 8 },
      { opacity: 1, y: 0, duration: 0.3, ease: 'power3.out', immediateRender: false },
      '<',
    )
  }
  const scrollTo = (name: string) => {
    const body = q('body')
    const target = q(name)
    const max = body.scrollHeight - q('viewport').clientHeight
    tl.to(body, {
      y: -Math.min(max, target.offsetTop - 4),
      duration: 0.6,
      ease: 'power2.inOut',
    })
  }

  step(0)
  move('tile-clean', { at: 0.3 })
  click('tile-clean')
  done('clean')
  clipboard('Copied Clean URL', CLEAN.url)
  wait(0.9)
  move('tile-md')
  click('tile-md')
  done('md')
  clipboard('Copied Markdown link', MARKDOWN)
  wait(1)

  step(1, '+=0.1')
  tl.to(q('clip'), { opacity: 0, duration: 0.2 })
  scrollTo('sec-tab')
  move('tile-pin', { at: '<0.3' })
  click('tile-pin')
  tl.set(q('pin-label'), { text: 'Unpin' }, '<')
  tl.set(q('pin-hint'), { text: 'Pinned' }, '<')
  tl.to(q('tile-pin'), { borderColor: 'rgba(56,189,248,0.5)', duration: 0.15 }, '<')
  tl.fromTo(
    q('chip-pinned'),
    { opacity: 0, scale: 0.8 },
    { opacity: 1, scale: 1, duration: 0.2, immediateRender: false },
    '<',
  )
  scrollTo('sec-page')
  move('zoom-in', { at: '<0.3' })
  ZOOMS.forEach((zoom, index) => {
    click('zoom-in')
    tl.set(q('zoom-value'), { text: `${Math.round(zoom * 100)}%` }, '<')
    tl.set(q('chip-zoom-text'), { text: `${Math.round(zoom * 100)}%` }, '<')
    tl.to(q('page-zoom'), { scale: zoom, duration: 0.3, ease: 'power2.out' }, '<')
    if (index === 0)
      tl.fromTo(
        q('chip-zoom'),
        { opacity: 0, scale: 0.8 },
        { opacity: 1, scale: 1, duration: 0.2, immediateRender: false },
        '<',
      )
  })
  wait(0.4)

  step(2, '+=0.1')
  move('edit-switch')
  click('edit-switch')
  tl.to(q('edit-switch'), { backgroundColor: '#f59e0b', duration: 0.15 }, '<')
  tl.to(q('edit-knob'), { x: 10, duration: 0.15 }, '<')
  tl.to(
    q('edit-row'),
    {
      borderColor: 'rgba(245,158,11,0.4)',
      backgroundColor: 'rgba(245,158,11,0.06)',
      duration: 0.2,
    },
    '<',
  )
  tl.set(q('edit-hint'), { text: 'Editing on. Reload to undo changes.' }, '<')
  tl.fromTo(
    q('chip-edit'),
    { opacity: 0, scale: 0.8 },
    { opacity: 1, scale: 1, duration: 0.2, immediateRender: false },
    '<',
  )
  move('headline', { ax: 0.98, ay: 0.55 })
  click('headline')
  tl.to(q('caret'), { opacity: 1, duration: 0.05 }, '<')
  type('edit-text', EDIT, { speed: 0.07 })
  tl.to(q('caret'), { opacity: 0, duration: 0.1, repeat: 3, yoyo: true })
  cursorOut('<')
  final('+=0.1')
  wait(1.4)

  tl.set(
    [q('clip'), q('chip-pinned'), q('chip-zoom'), q('chip-edit'), q('caret'), ...qa('ok')],
    { opacity: 0 },
    0,
  )
  tl.set(qa('tile-icon'), { opacity: 1 }, 0)
  tl.set(qa('tile'), { borderColor: 'var(--demo-tint-8)' }, 0)
  tl.set(q('body'), { y: 0 }, 0)
  tl.set(q('page-zoom'), { scale: 1 }, 0)
  tl.set(q('zoom-value'), { text: '100%' }, 0)
  tl.set(q('pin-label'), { text: 'Pin' }, 0)
  tl.set(q('pin-hint'), { text: 'Not pinned' }, 0)
  tl.set(q('edit-switch'), { backgroundColor: 'var(--demo-tint-12)' }, 0)
  tl.set(q('edit-knob'), { x: 0 }, 0)
  tl.set(
    q('edit-row'),
    { borderColor: 'var(--demo-tint-8)', backgroundColor: 'rgba(0,0,0,0)' },
    0,
  )
  tl.set(q('edit-hint'), { text: 'Click any text on the page to change it' }, 0)
  tl.set(q('edit-text'), { text: '' }, 0)
}

function Tile({
  d,
  icon: Icon,
  label,
  hint,
  accent = '#38bdf8',
  labelD,
  hintD,
}: {
  d: string
  icon: LucideIcon
  label: string
  hint?: string
  accent?: string
  labelD?: string
  hintD?: string
}) {
  return (
    <span
      data-d={`tile tile-${d}`}
      className="flex min-w-0 items-center gap-1.5 rounded-lg border bg-ink/[0.02] px-1.5 py-1"
      style={{ borderColor: 'var(--demo-tint-8)' }}
    >
      <span
        className="relative flex size-5 shrink-0 items-center justify-center rounded-md"
        style={{ backgroundColor: `${accent}1f`, color: accent }}
      >
        <Icon data-d={`tile-icon icon-${d}`} className="absolute size-2.5" />
        <CheckIcon data-d={`ok ok-${d}`} className="absolute size-2.5 text-emerald-400 opacity-0" />
      </span>
      <span className="min-w-0">
        <span data-d={labelD} className="block truncate text-[8px] font-medium text-ink">
          {label}
        </span>
        {hint ? (
          <span data-d={hintD} className="block truncate text-[6.5px] text-muted">
            {hint}
          </span>
        ) : null}
      </span>
    </span>
  )
}

function Chip({ d, children, tone }: { d?: string; children: ReactNode; tone: string }) {
  return (
    <span
      data-d={d}
      className="flex items-center gap-0.5 rounded-full border px-1 py-px text-[6.5px] font-medium"
      style={{ color: tone, borderColor: `${tone}55`, backgroundColor: `${tone}14` }}
    >
      {children}
    </span>
  )
}

function Panel() {
  return (
    <div className="flex h-full flex-col" style={{ width: PANEL }}>
      <DockHeader />
      <div className="p-2 pb-0">
        <section className="relative flex gap-2 overflow-hidden rounded-xl border border-line bg-[radial-gradient(120%_90%_at_0%_0%,rgba(56,189,248,0.12),transparent_60%)] p-2">
          <span className="flex size-7 shrink-0 items-center justify-center rounded-lg border border-line bg-canvas">
            <span className="size-3.5 rounded-sm bg-[#16a34a]" />
          </span>
          <span className="min-w-0 flex-1">
            <span className="line-clamp-2 block text-[8.5px] font-semibold leading-snug text-ink">
              {TITLE}
            </span>
            <span className="mt-0.5 flex min-w-0 items-center gap-0.5 text-[7px]">
              <LockIcon className="size-2 shrink-0 text-emerald-400" />
              <span className="shrink-0 font-medium text-ink-soft">{HOST}</span>
              <span className="truncate font-mono text-[6.5px] text-muted">{PATH}</span>
            </span>
            <span className="mt-1 flex flex-wrap gap-0.5">
              <Chip tone="#34d399">HTTPS</Chip>
              <Chip d="chip-pinned" tone="#38bdf8">
                <PinIcon className="size-1.5" /> Pinned
              </Chip>
              <Chip d="chip-zoom" tone="#a1a1aa">
                <ZoomInIcon className="size-1.5" /> <span data-d="chip-zoom-text">100%</span>
              </Chip>
              <Chip d="chip-edit" tone="#f59e0b">
                <PencilLineIcon className="size-1.5" /> Editing
              </Chip>
            </span>
          </span>
          <span className="flex shrink-0 flex-col gap-1 text-muted">
            <CopyIcon className="size-2.5" />
            <QrCodeIcon className="size-2.5" />
          </span>
        </section>
      </div>
      <div data-d="viewport" className="relative min-h-0 flex-1 overflow-hidden">
        <div data-d="body" className="space-y-2 p-2">
          <div>
            <p className="mb-1 text-[7.5px] font-semibold uppercase tracking-[0.12em] text-muted">
              Copy as
            </p>
            <div className="grid grid-cols-2 gap-1">
              {COPY_ITEMS.map((item) => (
                <Tile
                  key={item.key}
                  d={item.key}
                  icon={COPY_ICONS[item.key]}
                  label={item.label}
                  hint={item.hint}
                />
              ))}
            </div>
          </div>

          <div data-d="sec-tab">
            <p className="mb-1 text-[7.5px] font-semibold uppercase tracking-[0.12em] text-muted">
              Tab
            </p>
            <div className="grid grid-cols-4 gap-1">
              {[
                [ArrowLeftIcon, 'Back'],
                [ArrowRightIcon, 'Forward'],
                [RotateCwIcon, 'Reload'],
                [ZapIcon, 'Hard reload'],
              ].map(([Icon, label]) => {
                const I = Icon as LucideIcon
                return (
                  <span
                    key={label as string}
                    className="flex flex-col items-center gap-0.5 rounded-lg border border-line py-1 text-[6.5px] text-ink-soft"
                  >
                    <I className="size-2.5" />
                    {label as string}
                  </span>
                )
              })}
            </div>
            <div className="mt-1 grid grid-cols-3 gap-1">
              <Tile
                d="dup"
                icon={CopyPlusIcon}
                label="Duplicate"
                hint="Open a copy"
                accent="#34d399"
              />
              <Tile
                d="pin"
                icon={PinIcon}
                label="Pin"
                hint="Not pinned"
                accent="#34d399"
                labelD="pin-label"
                hintD="pin-hint"
              />
              <Tile d="mute" icon={Volume2Icon} label="Mute" hint="No audio" accent="#34d399" />
              <Tile
                d="win"
                icon={AppWindowIcon}
                label="New window"
                hint="Move tab out"
                accent="#34d399"
              />
              <Tile
                d="incog"
                icon={VenetianMaskIcon}
                label="Incognito"
                hint="Open privately"
                accent="#34d399"
              />
              <Tile
                d="shot"
                icon={CameraIcon}
                label="Screenshot"
                hint="Visible area"
                accent="#34d399"
              />
            </div>
          </div>

          <div data-d="sec-page">
            <p className="mb-1 text-[7.5px] font-semibold uppercase tracking-[0.12em] text-muted">
              Page
            </p>
            <div className="flex items-center justify-between rounded-lg border border-line px-1.5 py-1">
              <span className="text-[8px] font-medium text-ink">Page zoom</span>
              <span className="flex items-center gap-0.5">
                <span className="flex size-5 items-center justify-center rounded-md border border-line text-ink-soft">
                  <MinusIcon className="size-2.5" />
                </span>
                <span
                  data-d="zoom-value"
                  className="w-9 text-center font-mono text-[8px] font-semibold text-ink"
                >
                  100%
                </span>
                <span
                  data-d="zoom-in"
                  className="flex size-5 items-center justify-center rounded-md border border-line text-ink-soft"
                >
                  <PlusIcon className="size-2.5" />
                </span>
              </span>
            </div>
            <div
              data-d="edit-row"
              className="mt-1 flex items-center gap-1.5 rounded-lg border px-1.5 py-1"
              style={{ borderColor: 'var(--demo-tint-8)' }}
            >
              <span className="flex size-5 shrink-0 items-center justify-center rounded-md bg-amber-500/15 text-amber-400">
                <PencilLineIcon className="size-2.5" />
              </span>
              <span className="min-w-0 flex-1">
                <span className="block text-[8px] font-medium text-ink">Edit page text</span>
                <span data-d="edit-hint" className="block truncate text-[6.5px] text-muted">
                  Click any text on the page to change it
                </span>
              </span>
              <span
                data-d="edit-switch"
                className="flex h-3 w-[22px] shrink-0 items-center rounded-full px-0.5"
                style={{ backgroundColor: 'var(--demo-tint-12)' }}
              >
                <span data-d="edit-knob" className="size-2 rounded-full bg-white" />
              </span>
            </div>
            <div className="mt-1 grid grid-cols-3 gap-1">
              <Tile d="print" icon={PrinterIcon} label="Print" accent="#a78bfa" />
              <Tile d="top" icon={ArrowUpToLineIcon} label="Top" accent="#a78bfa" />
              <Tile d="bottom" icon={ArrowDownToLineIcon} label="Bottom" accent="#a78bfa" />
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

function Page() {
  return (
    <div className="relative h-full overflow-hidden bg-[#fafaf9]">
      <div data-d="page-zoom" className="origin-top-left px-4 pt-3 text-[#1c1917]">
        <p className="text-[7px] font-semibold uppercase tracking-[0.2em] text-[#16a34a]">
          Northwind Blog
        </p>
        <h3 data-d="headline" className="mt-1 text-[14px] font-bold leading-tight tracking-tight">
          {HEADLINE}
          <span data-d="edit-text" />
          <span
            data-d="caret"
            className="ml-px inline-block h-[13px] w-px translate-y-[2px] bg-[#1c1917] opacity-0"
          />
        </h3>
        <p className="mt-1 text-[7.5px] text-[#78716c]">Oct 24, 2026 · 6 min read</p>
        <div className="mt-2.5 space-y-1.5">
          {[96, 88, 92, 70, 0, 90, 84, 94, 62].map((width, index) =>
            width ? (
              <span
                key={index}
                className="block h-1.5 rounded-full bg-black/[0.08]"
                style={{ width: `${width}%` }}
              />
            ) : (
              <span key={index} className="block h-1" />
            ),
          )}
        </div>
        <div className="mt-3 h-16 rounded-lg bg-gradient-to-br from-[#bbf7d0] to-[#86efac]" />
      </div>
      <div
        data-d="clip"
        className="absolute inset-x-3 bottom-3 rounded-lg border border-ink/10 bg-elevated p-2 opacity-0 shadow-2xl"
      >
        <p className="flex items-center gap-1 text-[8px] font-medium text-ink">
          <CheckIcon className="size-2.5 text-emerald-400" />
          <span data-d="clip-title" />
        </p>
        <p
          data-d="clip-text"
          className="mt-1 break-all font-mono text-[7px] leading-snug text-ink-soft"
        />
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label={`Browser toolkit copying a clean URL with ${CLEAN.removed} tracking parameters removed and a Markdown link, pinning the tab, zooming to ${Math.round(ZOOMS[1] * 100)}%, and editing the page headline`}
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome url={URL_TEXT} panelWidth={PANEL} panel={<Panel />}>
        <Page />
      </BrowserChrome>
    </DemoStage>
  )
}
